style.css:
@-moz-document domain("google.com") {
html, body {
    background-color: #fef6f8 !important;
    color: #4d2b30 !important;
    font-family: 'Bell MT', serif !important;
  }

  /* Barra de búsqueda */
  .RNNXgb, .a4bIc, .gLFyf {
    background-color: #f8c9d3 !important;
    color: #4d2b30 !important;
    border: 2px solid #fcdde4 !important;
    border-radius: 30px !important;
    font-family: 'Bell MT', serif !important;
  }

  .gLFyf {
    color: #4d2b30 !important;
  }

  /* Botones de búsqueda */
  input[type="submit"], .RNmpXc {
    background-color: #f8c9d3 !important;
    color: white !important;
    border: none !important;
    padding: 8px 16px !important;
    border-radius: 20px !important;
    font-weight: bold;
    transition: 0.3s ease;
    font-family: 'Bell MT', serif !important;
  }

  input[type="submit"]:hover, .RNmpXc:hover {
    background-color: #fcdde4 !important;
  }

  /* Resultados */
  .rc, .g, .tF2Cxc {
    background-color: #ffffff !important;
    border: 1px solid #fcdde4 !important;
    border-radius: 12px !important;
    padding: 10px !important;
    margin-bottom: 12px !important;
    font-family: 'Bella MT', serif !important;
  }

  a, span, p, div {
    color: #b94776 !important;
    font-family: 'Bell MT', serif !important;
  }

  /* Footer */
  #fbar, .fbar {
    background-color: #f8c9d3 !important;
    color: white !important;
    font-family: 'Bell MT', serif !important;
  }

  /* Logo rosa */
  .lnXdpd {
    filter: hue-rotate(300deg) saturate(1.4) brightness(1.1);
  }
}
